INSERT INTO knowledge_base (symptom, synonym, feature, mechanism, syndrome) VALUES
  ('Đau mỏi gối', 'mỏi gối', 'Đau âm ỉ; thích xoa ấn; cảm giác mềm yếu vô lực', 'Thận âm là căn bản của âm dịch toàn thân, có vai trò nhu dưỡng, thấm nhuần các tổ chức tạng phủ, làm đầy não tủy, cân cốt, đồng thời chế ước phần dương quang của cơ thể. Khi Thận âm bất túc, não tủy, cốt tủy, cân cốt, nhĩ khiếu (tai) và tóc mất đi sự nuôi dưỡng, do đó xuất hiện các chứng váng đầu ù tai, hay quên, răng lung lay, tóc rụng, đau lưng mỏi gối, mềm yếu bất lực.', 'Thận âm hư'),
  ('Đau lưng ', 'Đau mỏi thắt lưng', 'Đau âm ỉ; thích xoa ấn; cảm giác mềm yếu vô lực', 'Thận âm là căn bản của âm dịch toàn thân, có vai trò nhu dưỡng, thấm nhuần các tổ chức tạng phủ, làm đầy não tủy, cân cốt, đồng thời chế ước phần dương quang của cơ thể. Khi Thận âm bất túc, não tủy, cốt tủy, cân cốt, nhĩ khiếu (tai) và tóc mất đi sự nuôi dưỡng, do đó xuất hiện các chứng váng đầu ù tai, hay quên, răng lung lay, tóc rụng, đau lưng mỏi gối, mềm yếu bất lực.', 'Thận âm hư'),
  (' ù tai', 'nhĩ minh', NULL, 'Thận âm là căn bản của âm dịch toàn thân, có vai trò nhu dưỡng, thấm nhuần các tổ chức tạng phủ, làm đầy não tủy, cân cốt, đồng thời chế ước phần dương quang của cơ thể. Khi Thận âm bất túc, não tủy, cốt tủy, cân cốt, nhĩ khiếu (tai) và tóc mất đi sự nuôi dưỡng, do đó xuất hiện các chứng váng đầu ù tai, hay quên, răng lung lay, tóc rụng, đau lưng mỏi gối, mềm yếu bất lực.', 'Thận âm hư'),
  ('Chóng mặt', 'Huyễn vựng; đầu váng', NULL, 'Thận âm là căn bản của âm dịch toàn thân, có vai trò nhu dưỡng, thấm nhuần các tổ chức tạng phủ, làm đầy não tủy, cân cốt, đồng thời chế ước phần dương quang của cơ thể. Khi Thận âm bất túc, não tủy, cốt tủy, cân cốt, nhĩ khiếu (tai) và tóc mất đi sự nuôi dưỡng, do đó xuất hiện các chứng váng đầu ù tai, hay quên, răng lung lay, tóc rụng, đau lưng mỏi gối, mềm yếu bất lực.', 'Thận âm hư'),
  ('đạo hãn', 'đổ mồ hôi trộm', NULL, 'Thận âm suy tổn dẫn đến hư nhiệt nội sinh, hư hỏa chưng bốc ra ngoài kinh lạc nên có triệu chứng triều nhiệt, đạo hãn, ngũ tâm phiền nhiệt, cốt chưng phát nhiệt, gò má đỏ', 'Thận âm hư'),
  ('Ngũ tâm phiền nhiệt', 'nóng lòng bàn tay, bàn chân và vùng ngực', NULL, 'Thận âm suy tổn dẫn đến hư nhiệt nội sinh, hư hỏa chưng bốc ra ngoài kinh lạc nên có triệu chứng triều nhiệt, đạo hãn, ngũ tâm phiền nhiệt, cốt chưng phát nhiệt, gò má đỏ', 'Thận âm hư'),
  ('Triều nhiệt ', 'sốt về chiều', NULL, 'Thận âm suy tổn dẫn đến hư nhiệt nội sinh, hư hỏa chưng bốc ra ngoài kinh lạc nên có triệu chứng triều nhiệt, đạo hãn, ngũ tâm phiền nhiệt, cốt chưng phát nhiệt, gò má đỏ', 'Thận âm hư'),
  ('cốt chưng', 'nóng âm ỉ trong xương', NULL, 'Thận âm suy tổn dẫn đến hư nhiệt nội sinh, hư hỏa chưng bốc ra ngoài kinh lạc nên có triệu chứng triều nhiệt, đạo hãn, ngũ tâm phiền nhiệt, cốt chưng phát nhiệt, gò má đỏ', 'Thận âm hư'),
  ('miệng khô họng táo', 'khô miệng', NULL, 'Thận âm suy tổn dẫn đến hư nhiệt nội sinh, tân dịch bị thiêu đốt gây miệng khô họng táo, tiểu tiện ít đỏ, đại tiện táo kết.', 'Thận âm hư'),
  ('Tiểu tiện ít đỏ', 'tiểu ít', NULL, 'Thận âm suy tổn dẫn đến hư nhiệt nội sinh, tân dịch bị thiêu đốt gây miệng khô họng táo, tiểu tiện ít đỏ, đại tiện táo kết.', 'Thận âm hư'),
  ('đại tiện táo kết', 'táo bón', NULL, 'Thận âm suy tổn dẫn đến hư nhiệt nội sinh, tân dịch bị thiêu đốt gây miệng khô họng táo, tiểu tiện ít đỏ, đại tiện táo kết.', 'Thận âm hư'),
  ('di tinh', 'tinh dịch rò rỉ tự nhiên ra ngoài', NULL, 'Thận âm suy tổn dẫn đến hư nhiệt nội sinh. Hư hỏa quấy động tinh thất (nơi chứa tinh) thì nhiếp nạp không vững, nam giới xuất hiện di tinh, xuất tinh sớm.', 'Thận âm hư'),
  ('xuất tinh sớm', NULL, NULL, 'Thận âm suy tổn dẫn đến hư nhiệt nội sinh. Hư hỏa quấy động tinh thất (nơi chứa tinh) thì nhiếp nạp không vững, nam giới xuất hiện di tinh, xuất tinh sớm.', 'Thận âm hư'),
  ('băng lậu', 'rong kinh; rong huyết; xuất huyết tử cung', NULL, 'Thận âm suy tổn dẫn đến hư nhiệt nội sinh. Hư hỏa bức huyết vọng hành thì nữ giới bị băng lậu.', 'Thận âm hư'),
  ('kinh nguyệt ít, bế kinh', NULL, NULL, 'Thận âm suy tổn, âm khuy dẫn đến nguồn hóa sinh kinh nguyệt bất túc thì kinh nguyệt ít hoặc bế kinh.', 'Thận âm hư'),
  ('Lưỡi đỏ', NULL, 'lưỡi đỏ; ít rêu hoặc không rêu', 'biểu hiện đặc trưng của âm dịch khuy tổn, hư nhiệt nội sinh.', 'Thận âm hư'),
  ('mạch tế sác', NULL, 'mạch nhỏ; nhanh', 'biểu hiện đặc trưng của âm dịch khuy tổn, hư nhiệt nội sinh.', 'Thận âm hư'),
  ('Đau mỏi gối', 'mỏi gối', 'Đau âm ỉ; thích xoa ấn; cảm giác mềm yếu vô lực', 'Can tạng chứa huyết, Thận tạng tàng tinh. Tinh và huyết đồng nguồn hóa sinh, Can và Thận đồng tông (cùng một gốc). Khi âm dịch của Can và Thận bất túc, thắt lưng và đầu gối thiếu sự tư nhuận nên dẫn đến thắt lưng đầu gối đau mỏi nhiễu mềm.', 'Can Thận âm hư'),
  ('Đau lưng ', 'Đau mỏi thắt lưng', 'Đau âm ỉ; thích xoa ấn; cảm giác mềm yếu vô lực', 'Can tạng chứa huyết, Thận tạng tàng tinh. Tinh và huyết đồng nguồn hóa sinh, Can và Thận đồng tông (cùng một gốc). Khi âm dịch của Can và Thận bất túc, thắt lưng và đầu gối thiếu sự tư nhuận nên dẫn đến thắt lưng đầu gối đau mỏi nhiễu mềm.', 'Can Thận âm hư'),
  ('Chóng mặt', 'Huyễn vựng ', 'tăng lên rõ rệt khi tức giận, lo âu, stress tinh thần', 'Can tạng chứa huyết, Thận tạng tàng tinh. Tinh và huyết đồng nguồn hóa sinh, Can và Thận đồng tông (cùng một gốc). Khi âm dịch của Can và Thận bất túc, thủy không hàm dưỡng được mộc, Can dương sẽ nhiễu động lên trên, do đó xuất hiện chứng trạng váng đầu mắt hoa', 'Can Thận âm hư'),
  ('Khô mắt', NULL, NULL, 'Can tạng chứa huyết, Thận tạng tàng tinh. Tinh và huyết đồng nguồn hóa sinh, Can và Thận đồng tông (cùng một gốc). Khi âm dịch của Can và Thận bất túc, nhãn mục (mắt) thiếu sự nuôi dưỡng của Can huyết và Thận âm dẫn đến hai mắt khô sáp', 'Can Thận âm hư'),
  (' ù tai', 'nhĩ minh', NULL, 'Can tạng chứa huyết, Thận tạng tàng tinh. Tinh và huyết đồng nguồn hóa sinh, Can và Thận đồng tông (cùng một gốc). Khi âm dịch của Can và Thận bất túc, tai mất đi sự thính nhạy của Thận khiếu nên gây ra tai ù tai điếc.', 'Can Thận âm hư'),
  ('hay quên', NULL, NULL, 'Can tạng chứa huyết, Thận tạng tàng tinh. Tinh và huyết đồng nguồn hóa sinh, Can và Thận đồng tông (cùng một gốc). Khi âm dịch của Can và Thận bất túc, tủy hải không đầy đủ gây ra chứng hay quên', 'Can Thận âm hư'),
  ('đạo hãn', 'đổ mồ hôi trộm', NULL, 'Thận âm suy tổn dẫn đến hư nhiệt nội sinh, hư hỏa chưng bốc ra ngoài kinh lạc nên có triệu chứng triều nhiệt, đạo hãn, ngũ tâm phiền nhiệt, cốt chưng phát nhiệt, gò má đỏ', 'Can Thận âm hư'),
  ('Ngũ tâm phiền nhiệt', 'nóng lòng bàn tay, bàn chân và vùng ngực', NULL, 'Thận âm suy tổn dẫn đến hư nhiệt nội sinh, hư hỏa chưng bốc ra ngoài kinh lạc nên có triệu chứng triều nhiệt, đạo hãn, ngũ tâm phiền nhiệt, cốt chưng phát nhiệt, gò má đỏ', 'Can Thận âm hư'),
  ('Triều nhiệt ', 'sốt về chiều', NULL, 'Thận âm suy tổn dẫn đến hư nhiệt nội sinh, hư hỏa chưng bốc ra ngoài kinh lạc nên có triệu chứng triều nhiệt, đạo hãn, ngũ tâm phiền nhiệt, cốt chưng phát nhiệt, gò má đỏ', 'Can Thận âm hư'),
  ('miệng khô họng táo', 'khô miệng', NULL, 'Thận âm suy tổn dẫn đến hư nhiệt nội sinh, tân dịch bị thiêu đốt gây miệng khô họng táo, tiểu tiện ít đỏ, đại tiện táo kết.', 'Can Thận âm hư'),
  ('Đau hông sườn', 'Hiếp thống; Đau sườn', 'Đau âm ỉ, căng tức dai dẳng vùng mạn sườn', 'Can mạch đi qua vùng hông sườn. Can Thận âm hư, mạch lạc ở hông sườn mất đi sự nhu dưỡng, do đó xuất hiện chứng đau âm ỉ vùng hông sườn.', 'Can Thận âm hư'),
  ('mất ngủ', 'thất miên', 'mất ngủ nhiều mộng', 'Hư hỏa quấy nhiễu lên trên làm tâm thần bất an, dẫn đến mất ngủ nhiều mộng', 'Can Thận âm hư'),
  ('di tinh', 'tinh dịch rò rỉ tự nhiên ra ngoài', NULL, 'Hư hỏa quấy động tinh thất, tinh quan đóng mở thất thường, dẫn đến chứng di tinh, xuất tinh sớm', 'Can Thận âm hư'),
  ('xuất tinh sớm', NULL, NULL, 'Hư hỏa quấy động tinh thất, tinh quan đóng mở thất thường, dẫn đến chứng di tinh, xuất tinh sớm', 'Can Thận âm hư'),
  ('kinh nguyệt ít', NULL, NULL, 'Âm dịch bất túc, xung nhâm thất đi sự đầy đặn và điều hòa, dẫn đến nữ giới kinh nguyệt ít.', 'Can Thận âm hư'),
  ('Lưỡi đỏ', NULL, 'lưỡi đỏ; ít rêu hoặc không rêu', 'biểu hiện đặc trưng của âm dịch khuy tổn, hư nhiệt nội sinh.', 'Can Thận âm hư'),
  ('mạch tế sác', NULL, 'mạch nhỏ; nhanh', 'biểu hiện đặc trưng của âm dịch khuy tổn, hư nhiệt nội sinh.', 'Can Thận âm hư');